package com.blessing.medbrain

import android.content.Context
import org.json.JSONObject

/** Original MedRebuild course text, not generated by the local model. */
object CardioCurriculum {
    data class Fiche(
        val id:String,val moduleId:String,val moduleTitle:String,
        val tome:Int,val order:Int,val title:String,val content:String,
        val objectives:List<String>,val essential:List<String>,
        val recall:List<String>,val sourceTitle:String,val sourceLocator:String
    )
    @Volatile private var saved:List<Fiche>?=null
    fun all(context:Context):List<Fiche> {
        saved?.let{return it}
        synchronized(this){
            saved?.let{return it}
            val src=context.assets.open("cardio-fiches-v18.json")
                .bufferedReader(Charsets.UTF_8).use{it.readText()}
            val root=JSONObject(src)
            require(root.optInt("schema")==1){"Format médical non reconnu"}
            val modules=root.getJSONArray("modules")
            val titles=HashMap<String,String>()
            for(i in 0 until modules.length()){
                val item=modules.getJSONObject(i)
                titles[item.getString("id")]=item.optString("title")
            }
            val items=root.getJSONArray("fiches")
            val result=ArrayList<Fiche>(items.length())
            fun strings(o:JSONObject,key:String):List<String>{
                val arr=o.optJSONArray(key)?:return emptyList()
                return (0 until arr.length()).mapNotNull{
                    arr.optString(it).takeIf{s->s.isNotBlank()}
                }
            }
            for(i in 0 until items.length()){
                val item=items.getJSONObject(i)
                val source=item.getJSONObject("source")
                val moduleId=item.getString("module_id")
                result.add(Fiche(
                    id=item.getString("id"),
                    moduleId=moduleId,
                    moduleTitle=titles[moduleId]?:moduleId,
                    tome=item.getInt("tome"),
                    order=item.optInt("order"),
                    title=item.getString("title"),
                    content=item.getString("content"),
                    objectives=strings(item,"objectives"),
                    essential=strings(item,"essential_points"),
                    recall=strings(item,"recall_prompts"),
                    sourceTitle=source.optString("title"),
                    sourceLocator=source.optString("locator")
                ))
            }
            require(result.size==156 && result.map{it.id}.toSet().size==156){
                "Corpus de cardiologie partiel ou corrompu"
            }
            saved=result
            return result
        }
    }
    fun forTome(context:Context,tome:Int):List<Fiche> =
        all(context).filter{it.tome==tome}
    fun get(context:Context,id:String):Fiche?=all(context).firstOrNull{it.id==id}
    /** Read 1 or up to 3 consecutive original fiches without crossing tome boundaries. */
    fun session(context:Context,id:String,expanded:Boolean):List<Fiche>{
        val selected=get(context,id)?:return emptyList()
        if(!expanded)return listOf(selected)
        val tome=forTome(context,selected.tome)
        val start=tome.indexOfFirst{it.id==id}
        return if(start<0)emptyList() else tome.drop(start).take(3)
    }

    /** Query the complete authored MedRebuild course independently of PDF ingestion. */
    fun findRelevant(context:Context,query:String,limit:Int=2):List<Fiche>{
        val tokens=SearchPolicy.terms(query).take(6)
        if(tokens.isEmpty())return emptyList()
        return all(context).mapNotNull{f->
            val title=SearchPolicy.normalized(f.title)
            val titleHits=tokens.count{title.contains(it)}
            val body=SearchPolicy.normalized(f.content)
            val coverage=tokens.count{title.contains(it)||body.contains(it)}
            // A single term mentioned only in the body of an unrelated fiche
            // is not enough to claim this is a relevant authored lesson.
            if(tokens.size==1 && titleHits==0)return@mapNotNull null
            // Requiring all of up to three distinct concepts avoids attributing
            // a cardiology fiche to an unrelated multi-concept medical question.
            val required=minOf(3,tokens.size)
            val relevance=SearchPolicy.score(query,f.title,f.content)
            if(coverage<required||relevance<=0.0)null
            else (titleHits*12.0+relevance) to f
        }.sortedWith(compareByDescending<Pair<Double,Fiche>>{it.first}
            .thenBy{it.second.tome}.thenBy{it.second.id})
            .take(limit.coerceIn(1,3)).map{it.second}
    }
    /** Resolve a previously recorded citation, never a random semantic re-search. */
    fun fromPreviousReferences(context:Context,sources:String):List<Fiche>{
        if(sources.isBlank())return emptyList()
        val ids=Regex("""\[MedRebuild, Google Docs, Tome [123], fiche (CARDIO\.T[123]\.M\d+\.F\d+)\]""")
            .findAll(sources).map{it.groupValues[1]}.distinct().take(2).toList()
        return ids.mapNotNull{get(context,it)}
    }
    fun references(fiches:List<Fiche>):String = fiches.take(2).joinToString("\n\n"){f->
        "[MedRebuild, Google Docs, Tome "+f.tome+", fiche "+f.id+"]\n"+
            "Document : "+f.sourceTitle+"\nRepère : "+f.sourceLocator
    }
    fun excerpt(f:Fiche,query:String,cap:Int=400):String{
        val terms=SearchPolicy.terms(query)
        val at=SearchPolicy.firstPosition(terms,f.content).coerceIn(0,f.content.length)
        val start=(at-90).coerceAtLeast(0)
        return f.content.substring(start,minOf(f.content.length,start+cap.coerceIn(100,600)))
            .replace(Regex("\\s+")," ").trim()
    }
}
